def system_language() -> str:
    """The language of this computer when it is one of ours (fr, zh, en), else English."""
    try:
        from PySide6.QtCore import QLocale

        name = QLocale.system().name()  # "zh_TW", "en_US", "pt_BR" ...
    except Exception:  # without Qt (tests, tools)
        import os

        name = (os.environ.get("LC_ALL") or os.environ.get("LANG") or "en").split(".")[0]
    name = name.replace("-", "_")
    head = name.partition("_")[0].lower()
    return head if head in _CODES else "en"


def set_language(code: str) -> None:
    global _current
    _current = code if code in _CODES else "en"  # one that is gone (ja, zh-TW ...): English
    import os

    os.environ["LUMEN_LANG"] = _current  # the tools (CodeTools, CodePDF ...) answer and draw in it; every child process inherits it
    from codedoctor.desktop import locale  # every other text, translated where it reaches the screen

    locale.install(_current)


def language() -> str:
    return _current


def tr(key: str, **fmt) -> str:
    texts = S.get(key)
    if texts is None:  # a sentence used as its own key (the 第二个窗口 notice crashed here, 2026-11-14): the catalogs translate it
        from codedoctor.desktop import locale

        try:
            text = locale.t(key)
        except Exception:
            text = key
        return text.format(**fmt) if fmt else text
    if _current == "zh-TW":
        from codedoctor.desktop import zh_hant

        text = zh_hant.convert(texts[0])
    else:
        text = texts[_ORDER.index(_current)] if _current in _ORDER else texts[1]
    return text.format(**fmt) if fmt else text
